---@class ExhibitUseView : ViewBase
ExhibitUseView = class("ExhibitUseView", ViewBase)

function ExhibitUseView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "ExhibitUseViewAction")
end

function ExhibitUseView:Awake()
    CommonHelper:HButtonSetCallback("BtnClose", self.gameObject, function(data)
        UIManager:Get():ClosePopup()
    end)
    self.PropCompoent=UIUtil.GetChild("PropCompoent",self.gameObject)
    self.BtnUse = CommonHelper:HButtonSetCallback("BtnUse", self.gameObject, function(hbtn)
        local serverID,slotID = PersonalHomeDataManager:Get().selfInfo:GetCanSetSite(self.Data:GetType())
        if serverID then
            if PersonalHomeDataManager:Get():TryUpdateExhibitNode(self.Data,serverID,slotID) then
                UINotify:Get():SendNotification(UINotifyEvent.PersonalHomeStorageView_SetData)
            end
        else
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.ExhibitCannotPut))
        end
        UIManager:Get():ClosePopup()
    end)
    self.BtnUnLoad = CommonHelper:HButtonSetCallback("BtnUnLoad", self.gameObject, function(hbtn)
        PersonalHomeDataManager:Get():TryUpdateExhibitNode(self.Data,nil,nil)
        UIManager:Get():ClosePopup()
    end)
end
---@param data ExhibitData
function ExhibitUseView:SetData(data,isUse)
    self.isUse=isUse
    CommonHelper:CSGameObjectSetActive(self.BtnUse.gameObject, isUse)
    CommonHelper:CSGameObjectSetActive(self.BtnUnLoad.gameObject,not isUse)
    self.Data = data
    local param = Param_PropSquareParam()
    param.id = self.Data:GetArticleID()
    param.showname = false
    if param.id~=nil then
        CommonHelper:SetPropSquareGroup(self.PropCompoent, param)
        self.type ,self.cfg = CommonHelper:GetPropTypeById(self.Data:GetArticleID())
        CommonHelper:SetText("###name", self.gameObject, CommonHelper:GetTempStr_Default(self.cfg.name))
        CommonHelper:SetText("###goodsdesctext", self.gameObject, CommonHelper:GetTempStr_Default(self.cfg.description))
    end
    if isUse then
        CommonHelper:SetText("###title", self.gameObject, CommonHelper:GetTempStr_Default(TemplateStringID.ExhibitInstall))
    else
        CommonHelper:SetText("###title", self.gameObject, CommonHelper:GetTempStr_Default(TemplateStringID.ExhibitUnload))
    end

end

function ExhibitUseView:OnClose()
    if not self.isUse then
        PersonalHomeHelper.SetIsCanOperationSign(true)
    end
end